-- payments-service schema (fixture for DDL snapshots and generated DB tests)
drop schema if exists pay cascade;
create schema pay;
create type pay.refund_reason as enum ('duplicate', 'fraud', 'customer_request');
create domain pay.money as numeric(12,2) check (value >= 0);
create table pay.customers (id bigserial primary key, email text not null unique, name text);
comment on table pay.customers is 'Who pays';
create table pay.payments (
  id bigint generated by default as identity primary key,
  customer_id bigint not null references pay.customers(id),
  amount numeric(12,2) not null check (amount > 0),
  fee numeric(12,2) not null default 0,
  status text not null default 'NEW' check (status in ('NEW', 'SETTLED', 'FAILED')),
  created_at timestamptz not null default now(),
  updated_at timestamptz
);
comment on column pay.payments.fee is 'Card fee: 2.9% + 0.30, at least 0.50';
create index payments_customer_status on pay.payments (customer_id, status);
create table pay.refunds (id bigserial primary key, payment_id bigint not null references pay.payments(id), reason pay.refund_reason not null, amount pay.money not null);
create function pay.touch() returns trigger language plpgsql as $$
begin
  NEW.updated_at := now();
  return NEW;
end $$;
create trigger payments_touch before update on pay.payments for each row execute function pay.touch();
create function pay.customer_balance(p_customer bigint) returns numeric language plpgsql stable as $$
declare settled numeric; refunded numeric;
begin
  select coalesce(sum(amount - fee), 0) into settled from pay.payments where customer_id = p_customer and status = 'SETTLED';
  select coalesce(sum(r.amount), 0) into refunded from pay.refunds r join pay.payments p on p.id = r.payment_id where p.customer_id = p_customer;
  return settled - refunded;
end $$;
create view pay.settled_payments as select p.id, p.customer_id, p.amount, p.fee from pay.payments p where p.status = 'SETTLED';
create view pay.customer_totals as select customer_id, sum(amount) as total from pay.settled_payments group by customer_id;
create table pay.unrelated_audit (id bigserial primary key, note text);
